export const gameView=`
<div class="dc-scenery" aria-hidden="true"><div class="dc-art"></div><div class="dc-camo"></div><div class="dc-scan"></div></div>
<header class="dc-header"><a class="dc-logo" href="#" data-dc="menu" aria-label="Design City main menu"><span>design</span><span>city</span></a><div class="dc-header-right"><strong data-dc-section>main menu</strong><button type="button" class="dc-sound" data-dc="sound" aria-pressed="false">sound off</button></div></header>
<section class="dc-panel dc-menu" data-view="menu"><div class="dc-menu-copy"><p class="dc-overline">Prathamesh presents</p><h2>good eye.<br>big city.</h2><p>A city of first impressions.<br>Make yours count.</p></div><nav aria-label="Design City main menu"><button type="button" data-dc="new">new game</button><button type="button" data-dc="resume" hidden>resume game</button><button type="button" data-dc="scores">high scores</button><button type="button" data-dc="options">options</button><button type="button" data-dc="help">how to play</button><button type="button" data-dc="quit">quit game</button></nav><small class="dc-credit">an original design challenge · inspired by the 1980s</small></section>
<section class="dc-panel dc-sheet" data-view="name" hidden><div class="dc-sheet-inner"><p class="dc-overline">A new face in town</p><h2>make a name.</h2><p>Your name appears on this device’s scoreboard.</p><form class="dc-name-form"><label for="dc-player-name">Player name</label><input id="dc-player-name" name="player" minlength="2" maxlength="20" required autocomplete="nickname" placeholder="Your alias" aria-describedby="dc-name-note"><small id="dc-name-note">2–20 characters. No account or email needed.</small><div class="dc-form-actions"><button class="dc-button" type="submit">let’s go</button><button class="dc-text-button" type="button" data-dc="menu">back</button></div><p class="dc-form-error" role="alert"></p></form><div class="dc-existing"><h3>or pick a returning player</h3><div data-dc-players></div></div></div></section>
<section class="dc-panel dc-story" data-view="story" hidden aria-label="Mission introduction"><div class="dc-story-image" aria-hidden="true"></div><div class="dc-story-shade" aria-hidden="true"></div><div class="dc-story-caption"><p class="dc-overline">Ocean Drive · after hours</p><h2><span>The city is watching.</span><span>Every detail matters.</span><span>Trust your eye.</span></h2></div><div class="dc-story-bottom"><span>loading your first assignment</span><div class="dc-load"><i></i></div><button type="button" data-dc="skip">skip intro</button></div></section>
<section class="dc-panel dc-play" data-view="play" hidden><div class="dc-hud"><div class="dc-player"><span data-dc-player></span><small data-dc-mode></small></div><div class="dc-hud-numbers"><span class="dc-clock" data-game-time>00:30</span><span class="dc-cash" data-game-score>000000</span><span class="dc-stars" aria-label="Reputation" data-dc-stars>☆☆☆☆☆</span></div></div><div class="dc-play-main"><aside class="dc-mission"><span class="dc-overline">your assignment</span><h2 data-dc-mission>colour<br>confidential.</h2><p data-dc-description>One shade doesn’t belong. Find it before the city clock runs out.</p><dl><div><dt>correct pick</dt><dd>+1 point</dd></div><div><dt>wrong pick</dt><dd>−2 seconds</dd></div><div><dt>personal best</dt><dd data-game-best>0</dd></div></dl><div class="dc-game-actions"><button type="button" class="dc-button" data-dc="pause">pause game</button><button type="button" class="dc-text-button" data-dc="menu">main menu</button></div><div class="dc-radar" aria-hidden="true"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="46" fill="#102b2c" stroke="#d8c7c5" stroke-width="3"/><path d="M19 20h32v22h33M15 66h70M33 9v77M64 13v76M10 44h25m16-2v46" fill="none" stroke="#759a93" stroke-width="7"/><path d="M33 10v76M64 13v76M10 44h25M51 42v46M15 66h70" fill="none" stroke="#c0c6ad" stroke-width="2"/><path d="m49 50 5 12-12-4z" fill="#f7c7e5" stroke="#142d2e" stroke-width="1.5"/><circle cx="69" cy="30" r="4" fill="#ef98cb"/></svg><span>design district</span></div></aside><div class="dc-board-wrap"><div class="dc-board-status"><span>spot the difference</span><span data-dc-level>level 01</span></div><div class="dc-board"><div class="dg-grid" role="group" aria-label="Visual identification game board"></div><div class="dc-pause-cover" hidden><strong>paused</strong><span>Your time is safe.</span></div></div><p class="dc-feedback" role="status" aria-live="polite"></p><small>Tap a tile · arrow keys + Enter · Esc for menu</small></div></div></section>
<section class="dc-panel dc-sheet dc-result" data-view="result" hidden><div class="dc-sheet-inner"><p class="dc-overline" data-dc-result-player></p><h2>mission<br>complete.</h2><strong class="dc-result-score" data-dc-final-score>0</strong><p data-dc-result-copy></p><p class="dc-save-status" role="status"></p><div class="dc-form-actions"><button type="button" class="dc-button" data-dc="again">play again</button><button type="button" class="dc-text-button" data-dc="scores">high scores</button><button type="button" class="dc-text-button" data-dc="menu">main menu</button></div></div></section>
<section class="dc-panel dc-sheet" data-view="options" hidden><div class="dc-sheet-inner"><p class="dc-overline">set your rules</p><h2>options.</h2><h3>assignment</h3><div class="dc-tabs" role="group" aria-label="Choose challenge"><button type="button" data-mode="colour" aria-pressed="true">colour</button><button type="button" data-mode="alignment" aria-pressed="false">alignment</button></div><p>Colour: find a different shade.<br>Alignment: find the misplaced middle line.</p><h3>radio</h3><button type="button" class="dc-button" data-dc="sound" aria-pressed="false">sound off</button><p>Original synth loop and arcade effects.<br>No sound outside the game.</p><button type="button" class="dc-text-button" data-dc="profile">manage player</button><button type="button" class="dc-text-button" data-dc="menu">back</button></div></section>
<section class="dc-panel dc-sheet" data-view="help" hidden><div class="dc-sheet-inner"><p class="dc-overline">a little street knowledge</p><h2>how to play.</h2><ol><li>Enter your name and choose Colour or Alignment in Options.</li><li>Find the one tile that breaks the pattern. Correct picks earn 1 point; wrong picks cost 2 seconds.</li><li>The grid gets harder as you score. You have 30 seconds.</li><li>Pause any time. Leaving the game automatically pauses the clock and sound.</li></ol><p>Use touch, mouse, or arrow keys + Enter. Press Esc to pause and return to the menu.</p><p class="dc-local-note">Rankings and player records stay in this browser. Clearing browser storage removes them. Scores are for fun and aren’t verified competition results.</p><button type="button" class="dc-text-button" data-dc="menu">back</button></div></section>
<section class="dc-panel dc-sheet dc-scores" data-view="scores" hidden><div class="dc-sheet-inner"><p class="dc-overline">the city’s sharpest eyes</p><h2>high scores.</h2><p class="dc-local-note">This device only · separate rankings for each challenge</p><div class="dc-tabs" role="group" aria-label="Scoreboard challenge"><button type="button" data-rank-mode="colour" aria-pressed="true">colour</button><button type="button" data-rank-mode="alignment" aria-pressed="false">alignment</button></div><div class="dc-record-stats" data-dc-record-stats></div><div class="dc-ranking" role="region" aria-label="Player rankings" tabindex="0"></div><div class="dc-form-actions"><button type="button" class="dc-text-button" data-dc="profile">my records</button><button type="button" class="dc-text-button" data-dc="menu">back</button></div></div></section>
<section class="dc-panel dc-sheet dc-profile" data-view="profile" hidden><div class="dc-sheet-inner"><p class="dc-overline">your record in the city</p><h2>player file.</h2><form class="dc-rename-form"><label for="dc-rename">Player name</label><input id="dc-rename" minlength="2" maxlength="20" required autocomplete="nickname"><button type="submit" class="dc-button">save name</button><p class="dc-profile-status" role="status"></p></form><div class="dc-history" role="region" aria-label="Your past games"></div><div class="dc-confirm" hidden><p class="dc-confirm-copy"></p><button type="button" class="dc-button" data-dc="confirm-delete">delete</button><button type="button" class="dc-text-button" data-dc="cancel-delete">cancel</button></div><div class="dc-form-actions"><button type="button" class="dc-text-button" data-dc="switch">switch player</button><button type="button" class="dc-text-button dc-danger" data-dc="delete-player">delete player</button><button type="button" class="dc-text-button" data-dc="menu">back</button></div></div></section>
<p class="dc-storage-note" role="status" hidden>Browser storage is unavailable. This session works, but records won’t survive a reload.</p>`;
